function applyPromotions(products,promotions){return (products||[]).map(p=>{const candidates=(promotions||[]).filter(x=>(x.product_id&&x.product_id===p.id)||(x.shop_id&&x.shop_id===p.shop_id)||(!x.product_id&&!x.shop_id));const promo=candidates.find(x=>x.product_id===p.id)||candidates.find(x=>x.shop_id===p.shop_id)||candidates.find(x=>!x.product_id&&!x.shop_id);if(!promo)return p;const amount=promotionAmount(promo,p.price);return {...p,discounted_price:Math.max(0,Number(p.price)-amount),discount_amount:amount,discount_label:promo.code||'PROMO'};});}
function Icon({type,size=21,filled=false}){const p={width:size,height:size,viewBox:'0 0 24 24',fill:filled?'currentColor':'none',stroke:'currentColor',strokeWidth:1.9,strokeLinecap:'round',strokeLinejoin:'round'};const d={home:<><path d="M3 10.8 12 3l9 7.8"/><path d="M5.5 9.8V21h13V9.8"/><path d="M9.5 21v-6h5v6"/></>,search:<><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></>,heart:<path d="M20.8 8.7c0 5-8.8 10.3-8.8 10.3S3.2 13.7 3.2 8.7A5 5 0 0 1 12 5.4a5 5 0 0 1 8.8 3.3Z"/>,bag:<><path d="M5 8.5h14l-1 12H6l-1-12Z"/><path d="M9 8.5V6a3 3 0 0 1 6 0v2.5"/></>,user:<><circle cx="12" cy="8" r="3.4"/><path d="M5 21c.7-3.4 3-5.2 7-5.2s6.3 1.8 7 5.2"/></>,back:<path d="m15 18-6-6 6-6"/>,plus:<><path d="M12 5v14M5 12h14"/></>,minus:<path d="M5 12h14"/>,trash:<><path d="M4 7h16"/><path d="M9 7V4h6v3M7 7l1 14h8l1-14"/><path d="M10 11v6M14 11v6"/></>,chevron:<path d="m9 18 6-6-6-6"/>,pin:<><path d="M12 21s7-6.1 7-12a7 7 0 1 0-14 0c0 5.9 7 12 7 12Z"/><circle cx="12" cy="9" r="2.3"/></>,card:<><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18"/></>,help:<><circle cx="12" cy="12" r="9"/><path d="M9.7 9a2.4 2.4 0 1 1 4 1.8c-1.2.8-1.7 1.3-1.7 2.5"/><path d="M12 17h.01"/></>,check:<path d="m5 12 4 4L19 6"/>,mic:<><path d="M12 15a3 3 0 0 0 3-3V7a3 3 0 0 0-6 0v5a3 3 0 0 0 3 3Z"/><path d="M19 12a7 7 0 0 1-14 0M12 19v3"/></>,photo:<><rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="8.5" cy="10" r="1.5"/><path d="m21 15-4-4-6 6"/></>,bell:<><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></>};return <svg {...p}>{d[type]}</svg>}
function BottomNav({tab,onTab,count}){const items=[['Home','home'],['Explore','search'],['Favorites','heart'],['Orders','bag'],['Profile','user']];return <nav className="bottom">{items.map(([label,icon])=><button key={label} className={tab===label?'selected':''} onClick={()=>onTab(label)}><span className="navicon"><Icon type={icon} size={20} filled={tab===label&&icon==='heart'}/>{label==='Orders'&&count>0&&<small>{count}</small>}</span><span>{label}</span></button>)}</nav>}
function Header({title,onBack,right}){return <div className="inner-head">{onBack&&<button className="icon-btn" onClick={onBack}><Icon type="back" size={21}/></button>}<h1>{title}</h1>{right||<span className="head-spacer"/>}</div>}
