useEffect(()=>{
  if(!supabaseConfigured)return;
  let mounted=true;

  const applySession=async(session)=>{
    if(!mounted)return;
    if(!session?.user){
      setProfile(null);
      return;
    }

    // Set the signed-in state immediately from the authenticated user.
    // The profile table is loaded afterward for the customer's saved details.
    const user=session.user;
    const metadata=user.user_metadata||{};
    setProfile({
      id:user.id,
      full_name:metadata.full_name||user.email||'Tumeni customer',
      phone:metadata.phone||'',
      email:user.email||'',
      avatar_url:metadata.avatar_url||'',
      role:metadata.account_type==='seller'?'partner':metadata.account_type==='agent'?'agent':'customer'
    });

    const r=await getCurrentProfile();
    if(mounted&&r.data)setProfile(r.data);
  };

  (async()=>{
    const [{data,error},{data:categoryData,error:categoryError},promotionResult]=await Promise.all([getProducts(),getCategories(),getActivePromotions()]);
    if(mounted){
      if(!error&&data){const mapped=data.map(p=>({...p,img:p.image_url,desc:p.description,category:p.categories?.name||'Other',shop:p.shop_id? p.shops?.name : 'Admin Product'}));setProducts(applyPromotions(mapped,promotionResult?.error?[]:(promotionResult?.data||[])));}
      else if(supabaseConfigured) setProducts([]);
      if(!categoryError&&categoryData) setCategories(categoryData);
    }

    const {data:{session}}=await supabase.auth.getSession();
    await applySession(session);
  })();

  const {data:listener}=supabase.auth.onAuthStateChange((_event,session)=>{
    void applySession(session);
  });

  return()=>{mounted=false;listener?.subscription?.unsubscribe()};
},[]);

useEffect(()=>{
  const params=new URLSearchParams(window.location.search);
  const payment=params.get('payment');

  if(payment==='complete'){
    setPaymentNotice({
      type:'success',
      text:'Payment confirmed by PayChangu. Your order is now paid.'
    });
    setPage('orders');
    setTab('Orders');
  }else if(payment==='failed'){
    setPaymentNotice({
      type:'error',
      text:'PayChangu did not confirm this payment. Your order remains unpaid.'
    });
    setPage('orders');
    setTab('Orders');
  }else if(payment==='verification_pending'){
    setPaymentNotice({
      type:'pending',
      text:'Payment response received. Tumeni is still verifying the payment.'
    });
    setPage('orders');
    setTab('Orders');
  }else if(payment==='error'){
    setPaymentNotice({
      type:'error',
      text:'Tumeni could not complete payment verification. Check your order status before trying again.'
    });
    setPage('orders');
    setTab('Orders');
  }

  if(payment){
    const cleanUrl=window.location.pathname+window.location.hash;
    window.history.replaceState({},document.title,cleanUrl);
  }
},[]);

const goTab=t=>{setTab(t);setProduct(null);setPage(t==='Home'?'home':t==='Explore'?'explore':t==='Orders'?'orders':t==='Profile'?'profile':'favorites')};const openYaza=()=>{setProduct(null);setPage('yaza-ai')};const runSearch=q=>{setSearchQuery(q);setProduct(null);setTab('Explore');setPage('explore')};const openNotifications=()=>{setProduct(null);setPage('notifications');setTab('Home')};
